CREATE SCHEMA IF NOT EXISTS university_q2;
SET search_path TO university_q2,public;
CREATE TABLE IF NOT EXISTS students(student_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_number VARCHAR(30) UNIQUE NOT NULL,full_name TEXT NOT NULL,fee_due NUMERIC(12,2) NOT NULL CHECK(fee_due>=0));
CREATE TABLE IF NOT EXISTS payments(payment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id INT NOT NULL REFERENCES students,amount NUMERIC(12,2) NOT NULL CHECK(amount>0),paid_on DATE NOT NULL);
CREATE TABLE IF NOT EXISTS payment_audit(audit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_id BIGINT NOT NULL REFERENCES payments,student_id INT NOT NULL REFERENCES students,amount NUMERIC(12,2) NOT NULL,logged_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS daily_collections(collection_date DATE PRIMARY KEY,payment_count BIGINT NOT NULL,total_amount NUMERIC(14,2) NOT NULL);
INSERT INTO students(student_id,student_number,full_name,fee_due) VALUES(1,'STU001','Amina Banda',5000),(2,'STU002','Brian Phiri',3500),(3,'STU003','Chanda Zulu',4200) ON CONFLICT(student_id) DO NOTHING;
CREATE OR REPLACE FUNCTION fn_fee_balance(p_student_id INT) RETURNS NUMERIC(12,2) LANGUAGE plpgsql AS $$
DECLARE v_due NUMERIC(12,2); v_paid NUMERIC(12,2);
BEGIN SELECT fee_due INTO v_due FROM students WHERE student_id=p_student_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown student %',p_student_id; END IF; SELECT COALESCE(sum(amount),0) INTO v_paid FROM payments WHERE student_id=p_student_id; RETURN v_due-v_paid; END $$;
CREATE OR REPLACE FUNCTION fn_payment_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN INSERT INTO payment_audit(payment_id,student_id,amount) VALUES(NEW.payment_id,NEW.student_id,NEW.amount); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_payment_audit ON payments;
CREATE TRIGGER trg_payment_audit AFTER INSERT ON payments FOR EACH ROW EXECUTE FUNCTION fn_payment_audit();
CREATE OR REPLACE PROCEDURE pr_receive_payment(p_student_id INT,p_amount NUMERIC,p_paid_on DATE) LANGUAGE plpgsql AS $$
DECLARE v_balance NUMERIC(12,2);
BEGIN IF p_amount IS NULL OR p_amount<=0 OR p_paid_on IS NULL THEN RAISE EXCEPTION 'Positive amount and payment date required'; END IF; v_balance:=fn_fee_balance(p_student_id); IF p_amount>v_balance THEN RAISE EXCEPTION 'Payment exceeds outstanding balance %',v_balance; END IF; INSERT INTO payments(student_id,amount,paid_on) VALUES(p_student_id,p_amount,p_paid_on); END $$;
CALL pr_receive_payment(1,1000,CURRENT_DATE-2); CALL pr_receive_payment(1,500,CURRENT_DATE-1); CALL pr_receive_payment(2,700,CURRENT_DATE-2); CALL pr_receive_payment(2,300,CURRENT_DATE-1); CALL pr_receive_payment(2,500,CURRENT_DATE); CALL pr_receive_payment(1,250,CURRENT_DATE);
CREATE OR REPLACE VIEW v_fee_balances AS SELECT s.student_number,s.full_name,fn_fee_balance(s.student_id) AS outstanding_balance FROM students s WHERE fn_fee_balance(s.student_id)>0;
CREATE INDEX IF NOT EXISTS ix_payments_student_paid_on ON payments(student_id,paid_on);
EXPLAIN SELECT * FROM payments WHERE student_id=1 AND paid_on BETWEEN CURRENT_DATE-30 AND CURRENT_DATE;
CREATE OR REPLACE PROCEDURE pr_refresh_collections(p_day DATE) LANGUAGE plpgsql AS $$
BEGIN IF p_day IS NULL THEN RAISE EXCEPTION 'Date required'; END IF; INSERT INTO daily_collections SELECT p_day,count(*),COALESCE(sum(amount),0) FROM payments WHERE paid_on=p_day ON CONFLICT(collection_date) DO UPDATE SET payment_count=EXCLUDED.payment_count,total_amount=EXCLUDED.total_amount; END $$;
CALL pr_refresh_collections(CURRENT_DATE-1);
-- Schedule daily at 01:00: CALL university_q2.pr_refresh_collections(CURRENT_DATE-1); configure with pgAgent or pg_cron.
SELECT * FROM v_fee_balances; SELECT * FROM payment_audit; SELECT * FROM daily_collections;